// ---------------------------------------------------------------------------
// Ingestion (idempotent)
// ---------------------------------------------------------------------------
async function ingestCorpus(
  client: InstanceType<typeof AlchemystAI>,
  runId: string
): Promise<void> {
  const corpus = buildCorpus();
  const scope = 'internal';
  const source = `threshold-cli-${runId}`;

  const documents = corpus.map((d) => ({
    content: d.content,
    title: d.title,
  }));

  const lastModified = new Date().toISOString();

  for (let i = 0; i < documents.length; i++) {
    const fileName = `threshold_doc_${i}_${runId}.md`;
    const doc = documents[i];
    try {
      await client.v1.context.add({
        context_type: 'resource',
        documents: [
          {
            content: doc.content,
            title: doc.title,
          },
        ],
        scope,
        source,
        metadata: {
          fileName,
          fileType: 'text/markdown',
          groupName: [`threshold-cli`, `run-${runId}`],
          lastModified,
        },
      });
      // Stagger ingestion slightly to avoid rate-limit issues.
      await new Promise((r) => setTimeout(r, 250));
    } catch (err: unknown) {
      if (err instanceof ConflictError) {
        // Idempotency: 409 means the document is already stored for this run.
        process.stderr.write(
          `[ingest] 409 conflict on ${fileName}; treating as success (idempotent).\n`
        );
        continue;
      }
      // Some SDK errors may wrap the status; check shape defensively.
      const status =
        err && typeof err === 'object' && 'status' in err
          ? (err as { status?: unknown }).status
          : undefined;
      if (status === 409 || status === '409') {
        process.stderr.write(
          `[ingest] 409 conflict on ${fileName}; treating as success (idempotent).\n`
        );
        continue;
      }
      throw err;
    }
  }
}

// ---------------------------------------------------------------------------
// Search
// ---------------------------------------------------------------------------
const QUERY =
  'What are the benefits of regular exercise for cardiovascular health?';
const SCOPE = 'internal';

async function searchCount(
  client: InstanceType<typeof AlchemystAI>,
  threshold: number
): Promise<number> {
  const res = await client.v1.context.search({
    query: QUERY,
    similarity_threshold: threshold,
    minimum_similarity_threshold: 0,
    scope: SCOPE,
  });
  const contexts = (res && (res as { contexts?: unknown[] }).contexts) || [];
  return Array.isArray(contexts) ? contexts.length : 0;
}

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------
async function main(): Promise<void> {
  const args = parseArgs(process.argv.slice(2));

  const apiKey = process.env.ALCHEMYST_AI_API_KEY;
  if (!apiKey || apiKey.trim() === '') {
    process.stderr.write(
      'Error: ALCHEMYST_AI_API_KEY environment variable is not set.\n'
    );
    process.exit(1);
  }

  const runId = readRunId();

  const client = new AlchemystAI({ apiKey });

  process.stderr.write(
    `[threshold-cli] run-id=${runId} thresholds=${args.thresholds.join(',')}\n`
  );

  // 1. Ingest the corpus (idempotent).
  await ingestCorpus(client, runId);

  // Small grace period for indexing before searching.
  await new Promise((r) => setTimeout(r, 1500));

  // 2. Search at each threshold and count contexts.
  const results: Array<{ threshold: number; count: number }> = [];
  for (const t of args.thresholds) {
    let count = 0;
    try {
      count = await searchCount(client, t);
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      process.stderr.write(
        `[threshold-cli] search failed at threshold=${t}: ${msg}\n`
      );
      throw err;
    }
    results.push({ threshold: t, count });
    process.stderr.write(
      `[threshold-cli] threshold=${t} count=${count}\n`
    );
  }

  const out = {
    query: QUERY,
    results,
  };

  process.stdout.write(JSON.stringify(out) + '\n');
}

main().catch((err) => {
  const msg = err instanceof Error ? err.stack || err.message : String(err);
  process.stderr.write(`[threshold-cli] fatal: ${msg}\n`);
  process.exit(1);
});
