const QUERY =
  'What are the benefits of regular exercise for cardiovascular health?';
const SCOPE = 'internal';

async function searchCount(
  client: InstanceType<typeof AlchemystAI>,
  threshold: number
): Promise<number> {
  const res = await client.v1.context.search({
    query: QUERY,
    similarity_threshold: threshold,
    minimum_similarity_threshold: 0,
    scope: SCOPE,
  });
  const contexts = (res && (res as { contexts?: unknown[] }).contexts) || [];
  return Array.isArray(contexts) ? contexts.length : 0;
}

