// ---------------------------------------------------------------------------
// Ingestion (idempotent)
// ---------------------------------------------------------------------------
async function ingestCorpus(
  client: InstanceType<typeof AlchemystAI>,
  runId: string
): Promise<void> {
  const corpus = buildCorpus();
  const scope = 'internal';
  const source = `threshold-cli-${runId}`;

  const documents = corpus.map((d) => ({
    content: d.content,
    title: d.title,
  }));

  const lastModified = new Date().toISOString();

  for (let i = 0; i < documents.length; i++) {
    const fileName = `threshold_doc_${i}_${runId}.md`;
    const doc = documents[i];
    try {
      await client.v1.context.add({
        context_type: 'resource',
        documents: [
          {
            content: doc.content,
            title: doc.title,
          },
        ],
        scope,
        source,
        metadata: {
          fileName,
          fileType: 'text/markdown',
          groupName: [`threshold-cli`, `run-${runId}`],
          lastModified,
        },
      });
      // Stagger ingestion slightly to avoid rate-limit issues.
      await new Promise((r) => setTimeout(r, 250));
    } catch (err: unknown) {
      if (err instanceof ConflictError) {
        // Idempotency: 409 means the document is already stored for this run.
        process.stderr.write(
          `[ingest] 409 conflict on ${fileName}; treating as success (idempotent).\n`
        );
        continue;
      }
      // Some SDK errors may wrap the status; check shape defensively.
      const status =
        err && typeof err === 'object' && 'status' in err
          ? (err as { status?: unknown }).status
          : undefined;
      if (status === 409 || status === '409') {
        process.stderr.write(
          `[ingest] 409 conflict on ${fileName}; treating as success (idempotent).\n`
        );
        continue;
      }
      throw err;
    }
  }
}

// ---------------------------------------------------------------------------
// Search
// ---------------------------------------------------------------------------
const QUERY =
  'What are the benefits of regular exercise for cardiovascular health?';
const SCOPE = 'internal';

async function searchCount(
  client: InstanceType<typeof AlchemystAI>,
  threshold: number
): Promise<number> {
  const res = await client.v1.context.search({
    query: QUERY,
    similarity_threshold: threshold,
    minimum_similarity_threshold: 0,
    scope: SCOPE,
  });
  const contexts = (res && (res as { contexts?: unknown[] }).contexts) || [];
  return Array.isArray(contexts) ? contexts.length : 0;
}

// ---------------------------------------------------------------------------
// Main
// ---------------------------------------------------------------------------
async function main(): Promise<void> {
  const args = parseArgs(process.argv.slice(2));

